style.css:
@-moz-document domain("substack.com") {
/* A scope that RE-DECLARES the token scale from a source we do NOT already own
     must be listed here: a declaration on the element itself beats an inherited
     !important from :root. `.substack-theme` and `.light-theme` re-declare the whole
     --color-light-* family (quote/highlight restack cards in the feed sit inside
     one); `.force-light-theme` hardcodes the legacy --web_bg_color/
     --background_contrast_* scale.
     Scopes that rebind onto the --color-light- or --color-bg- families
     (`.pubAccentTheme-`, `.bg-elevated-`, `.elevatedTheme-`, the :hover row
     rebinds) need no entry — they resolve through the values this block already
     sets. Scopes fed by a PUB-CONFIGURED input (`.headerTheme-`, `.footerTheme-`,
     `.footerSecondaryTheme-`, `.subscribeTheme-`) are covered by darkening that
     input below, in the --header_, --footer_ and --subscribe_ families. */
  :root,
  .substack-theme,
  .light-theme,
  .force-light-theme,
  [class*="pubTheme"],
  [class*="headerTheme"] {
    color-scheme: dark;

    /* --- Neutral background scale -> dark --- */
    --color-bg-primary: #14181d !important;
    --color-bg-primary-themed: #14181d !important;
    --color-bg-primary-hover: #1a1f26 !important;
    --color-bg-primary-hover-themed: #1a1f26 !important;
    --color-bg-secondary: #1c2128 !important;
    --color-bg-secondary-themed: #1c2128 !important;
    --color-bg-secondary-hover-themed: #262c33 !important;
    --color-bg-tertiary: #262c33 !important;
    --color-bg-tertiary-themed: #262c33 !important;
    --color-bg-quaternary: #2d333b !important;
    --color-bg-elevated-primary: #1c2128 !important;
    --color-bg-elevated-secondary: #262c33 !important;
    --color-bg-elevated-tertiary: #363b42 !important;
    --color-bg-elevated-themed: #1c2128 !important;
    --color-bg-elevated-hover-themed: #262c33 !important;
    --color-bg-sunken-primary: #0d1117 !important;
    --web_bg_color: #14181d !important;
    --background_contrast_1: #1c2128 !important;
    --background_contrast_2: #262c33 !important;
    --background_contrast_3: #363b42 !important;
    --background_contrast_4: #4a515a !important;
    --background_contrast_5: #8b949e !important;

    /* --- Foreground / text scale -> light --- */
    --color-fg-primary: #e6edf3 !important;
    --color-fg-primary-themed: #e6edf3 !important;
    --color-fg-secondary: #c4cdd6 !important;
    --color-fg-secondary-themed: #c4cdd6 !important;
    --color-fg-tertiary: #8b949e !important;
    --color-fg-tertiary-themed: #8b949e !important;
    --print_on_web_bg_color: #e6edf3 !important;
    --print_secondary_on_web_bg_color: #8b949e !important;

    /* --- Semantic INK (mentions, link previews, status/paid/live labels) ---
       Every `--color-semantic-*-fg-primary` keeps its light-scheme value here, and
       these are text colors: the mention blue #0083d5 measures 4.42:1 on the #14181d
       canvas (AA fail). Each value below is the site's OWN dark-scheme ink
       (--color-dark-semantic-*-fg-primary), so the semantics stay the site's.
       The matching -bg-primary* fills are untouched — they carry white ink and are
       identical in both schemes. Both the alias and the --color-light-* source are
       set: some rules reference the light token by name. */
    --color-semantic-highlight-fg-primary: rgb(24, 160, 251) !important;
    --color-light-semantic-highlight-fg-primary: rgb(24, 160, 251) !important;
    --color-semantic-select-fg-primary: rgb(0, 118, 255) !important;
    --color-light-semantic-select-fg-primary: rgb(0, 118, 255) !important;
    --color-semantic-error-fg-primary: rgb(255, 119, 114) !important;
    --color-light-semantic-error-fg-primary: rgb(255, 119, 114) !important;
    --color-semantic-success-fg-primary: rgb(82, 221, 152) !important;
    --color-light-semantic-success-fg-primary: rgb(82, 221, 152) !important;
    --color-semantic-warn-fg-primary: rgb(255, 223, 65) !important;
    --color-light-semantic-warn-fg-primary: rgb(255, 223, 65) !important;
    --color-semantic-paid-fg-primary: rgb(155, 125, 255) !important;
    --color-light-semantic-paid-fg-primary: rgb(155, 125, 255) !important;
    --color-semantic-substack-fg-primary: rgb(255, 133, 61) !important;
    --color-light-semantic-substack-fg-primary: rgb(255, 133, 61) !important;

    /* --- Borders / hairlines --- */
    --color-utility-detail: rgba(255, 255, 255, 0.1) !important;
    --color-utility-detail-themed: #2d333b !important;
    --border-primary-themed: 1px solid #2d333b !important;

    /* --- Light-scheme primitives (direct references + OS-light hub) -> dark --- */
    --color-light-bg-primary: #14181d !important;
    --color-light-bg-primary-hover: #1a1f26 !important;
    --color-light-bg-secondary: #1c2128 !important;
    --color-light-bg-tertiary: #262c33 !important;
    --color-light-bg-quaternary: #2d333b !important;
    --color-light-bg-elevated-primary: #1c2128 !important;
    --color-light-bg-elevated-secondary: #262c33 !important;
    --color-light-bg-elevated-tertiary: #363b42 !important;
    --color-light-bg-sunken-primary: #0d1117 !important;
    --color-light-fg-primary: #e6edf3 !important;
    --color-light-fg-secondary: #c4cdd6 !important;
    --color-light-fg-tertiary: #8b949e !important;
    --color-light-utility-detail: rgba(255, 255, 255, 0.1) !important;

    /* --- Publication-themed surface family (--color_theme_*, --cover_*).
       The pop/accent members are deliberately left untouched to keep each
       newsletter's own accent color. --color_theme_print_on_pop stays white
       (it is the text that sits on the accent). --- */
    --color_theme_bg_elevated: #1c2128 !important;
    --color_theme_bg_elevated_secondary: #262c33 !important;
    --color_theme_bg_elevated_tertiary: #363b42 !important;
    --color_theme_bg_contrast_1: #1c2128 !important;
    --color_theme_bg_contrast_2: #262c33 !important;
    --color_theme_bg_contrast_3: #363b42 !important;
    --color_theme_bg_contrast_4: #4a515a !important;
    --color_theme_bg_contrast_5: #8b949e !important;
    --color_theme_detail: #2d333b !important;
    --cover_bg_color: #14181d !important;
    --cover_bg_color_secondary: #1c2128 !important;
    --cover_print_primary: #e6edf3 !important;
    --cover_print_secondary: #c4cdd6 !important;
    --cover_print_tertiary: #8b949e !important;

    /* --- Publication header surface family (--header_*).
       Neutral header backgrounds and their contrast/print scale -> dark, mirroring
       the cover family. Branded (saturated) headers darken the same way covers do. --- */
    --header_bg_color: #14181d !important;
    --header_bg_elevated: #1c2128 !important;
    --header_bg_elevated_secondary: #262c33 !important;
    --header_bg_elevated_tertiary: #363b42 !important;
    --header_bg_contrast_1: #1c2128 !important;
    --header_bg_contrast_2: #262c33 !important;
    --header_bg_contrast_3: #363b42 !important;
    --header_bg_contrast_4: #4a515a !important;
    --header_detail_color: #2d333b !important;
    --print_on_header_bg_color: #e6edf3 !important;
    --print_secondary_on_header_bg_color: #8b949e !important;

    /* --- Publication footer + subscribe-widget surface families
       (--footer_, --footer_secondary_ and --subscribe_).
       Same mechanism as the --header_ and --cover_ families: the pub's design
       settings emit these on :root, and the .footerTheme-, .footerSecondaryTheme-
       and .subscribeTheme- wrappers rebind the whole --color-bg-, --color-fg- and
       --web_bg_color scale onto them. Those wrappers do not always carry
       `pubTheme`, so the scope list alone does not reach them — the pub-configured
       INPUT has to be dark too. --- */
    --footer_bg_color: #14181d !important;
    --footer_bg_elevated: #1c2128 !important;
    --footer_bg_elevated_secondary: #262c33 !important;
    --footer_bg_elevated_tertiary: #363b42 !important;
    --footer_bg_contrast_1: #1c2128 !important;
    --footer_bg_contrast_2: #262c33 !important;
    --footer_bg_contrast_3: #363b42 !important;
    --footer_detail_color: #2d333b !important;
    --print_on_footer_bg_color: #e6edf3 !important;
    --print_secondary_on_footer_bg_color: #8b949e !important;
    --footer_secondary_bg_color: #14181d !important;
    --footer_secondary_bg_elevated: #1c2128 !important;
    --footer_secondary_bg_elevated_secondary: #262c33 !important;
    --footer_secondary_bg_elevated_tertiary: #363b42 !important;
    --footer_secondary_bg_contrast_1: #1c2128 !important;
    --footer_secondary_bg_contrast_2: #262c33 !important;
    --footer_secondary_bg_contrast_3: #363b42 !important;
    --footer_secondary_detail_color: #2d333b !important;
    --print_on_footer_secondary_bg_color: #e6edf3 !important;
    --print_secondary_on_footer_secondary_bg_color: #8b949e !important;
    --subscribe_bg_color: #14181d !important;
    --subscribe_bg_elevated: #1c2128 !important;
    --subscribe_bg_elevated_secondary: #262c33 !important;
    --subscribe_bg_elevated_tertiary: #363b42 !important;
    --subscribe_bg_contrast_1: #1c2128 !important;
    --subscribe_bg_contrast_2: #262c33 !important;
    --subscribe_bg_contrast_3: #363b42 !important;
    --subscribe_detail_color: #2d333b !important;
    --print_on_subscribe_bg_color: #e6edf3 !important;
    --print_secondary_on_subscribe_bg_color: #8b949e !important;

    /* Slightly deeper scrim on dark */
    --color-utility-modal: rgba(0, 0, 0, 0.65) !important;
  }

  /* --- Page canvas (html bg is hardcoded white, not token-driven) --- */
  html,
  body {
    background-color: #14181d !important;
  }

  /* --- Reader/app shell palette (substack.com hub: profile, chat, inbox, notes) ---
     `.pc-root.app-theme` and `.appTheme-*` remap the whole --color-* scale onto
     --color-app-light-*, which the page declares on `body` in an inline <style> AND
     again in a style ATTRIBUTE on each appTheme node (that copy also carries the
     publication's accent). A :root-level override cannot reach either, so under an
     OS LIGHT scheme the entire hub paints white. Redefining the source family here
     also carries the 50+ derived button/link/UFI tokens.
     --color-app-light-accent* / -bg-accent* stay untouched (brand orange). --- */
  body,
  [class*="appTheme"] {
    --color-app-light-fg-primary: #e6edf3 !important;
    --color-app-light-fg-secondary: #c4cdd6 !important;
    --color-app-light-fg-tertiary: #8b949e !important;
    --color-app-light-bg-primary: #14181d !important;
    --color-app-light-bg-primary-hover: #1a1f26 !important;
    --color-app-light-bg-secondary: #1c2128 !important;
    --color-app-light-bg-tertiary: #262c33 !important;
    --color-app-light-bg-quaternary: #2d333b !important;
  }

  /* --- App-shell nav logo ---
     `.pc-root.app-theme` (substack.com pages that carry a publication's
     appTheme, e.g. every /@handle profile) aliases --color-nav-logo to
     --color-bg-quaternary — a SURFACE token, so our #2d333b paints the
     wordmark at 1.4:1 (the site's own #b6b6b6 reads on white). The alias only
     exists inside this scope; on the hub and explore, :root keeps
     --color-nav-logo at the brand orange, so this must NOT be set globally. --- */
  .pc-root.app-theme,
  [class*="appTheme"] {
    --color-nav-logo: #8b949e !important;
  }

  /* --- Code blocks (posts ship plain <pre>/<code>, no highlight classes) --- */
  pre,
  code,
  kbd,
  samp {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }
  pre code {
    background-color: transparent !important;
  }

  /* --- Inputs / textareas ---
     Subscribe email inputs carry the publication's accent border (part of the
     accent-preservation feature), so the neutral border override skips them.
     `emailInputOnAccentBackground` sits inside the "Ready for more?" band that
     the pub's accent already paints, and takes that accent as its own fill with
     white ink + a white hairline; filling it dark drops a navy box into the
     accent band, so it keeps the site's fill, ink AND placeholder.
     Checkboxes and radios are excluded: they render with `appearance: auto`,
     so a background-color override replaces the whole native widget paint —
     including the tick/dot — and a checked box becomes indistinguishable from
     an unchecked one (the /sponsorships-signup vertical pickers). Left alone
     they follow the `color-scheme: dark` set on :root.
     The button-ish types are excluded for the same reason a `<button>` is not
     in this list at all: they are CONTROLS, not fields, and carry their own
     fill. The help centre's `input[type="submit"]` search CTA is the brand
     orange (#ff7731) with white ink. --- */
  input:not([class*="emailInputOnAccentBackground"]):not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]):not([type="reset"]):not([type="image"]),
  textarea,
  select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }
  /* The `:not(:focus)` guard is load-bearing: Pencraft paints the focus ring as
     `border: var(--border-focus)` (the pub accent inside a pub scope, the select
     blue in the app shell). A blanket `border-color` override outranks it and
     leaves only a 20%-alpha glow as the focus cue. Skipping the focused state
     hands the border back to the site rather than restating it — elements the
     site leaves border-less on focus (the comment textarea) stay border-less. */
  input:not([class*="emailInput"]):not([class*="email-input"]):not([type="checkbox"]):not([type="radio"]):not([type="submit"]):not([type="button"]):not([type="reset"]):not([type="image"]):not(:focus),
  textarea:not(:focus),
  select:not(:focus) {
    border-color: #2d333b !important;
  }
  input:not([class*="emailInputOnAccentBackground"])::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
  }

  /* --- Empty image placeholders (Pencraft gallery/thumbnail stages) --- */
  [class*="containerEmpty"],
  [class*="imagePlaceholder"] {
    background-color: #1c2128 !important;
  }

  /* --- Welcome / intro popup (hardcoded white container) --- */
  .intro-popup {
    background-color: #1c2128 !important;
  }

  /* --- Discover/explore selected category tab ---
     The active category pill (Radix tab styled as a filled secondary button)
     ships a bright white background with dark text. Darken to an elevated
     surface so it reads as "selected" without a white block on the dark bar.
     Scoped to priority_secondary so accent/underline pub nav tabs are untouched. --- */
  [role="tab"][aria-selected="true"][class*="priority_secondary"] {
    background-color: #363b42 !important;
    color: #e6edf3 !important;
  }

  /* --- Archive month dividers ---
     The grouped-archive month header takes the pub accent as INK. It shares the
     `meta-` family with the byline dates below it, so it takes their muted grey
     rather than the neutral used by the accent-ink block below. --- */
  [class*="monthHeader"] {
    color: #8b949e !important;
  }

  /* --- Accent used as INK ---
     A publication configures ONE accent, emitted as both a fill (--background_pop)
     and an ink (--print_pop, and the --color-accent-text token every Pencraft
     accent-ink consumer reads). The fill is left alone — that is where the brand
     lives — but the ink is pub-configured and may be arbitrarily dark, and no
     static CSS can lighten only the dark ones: post-body links measure 1.76:1 on
     #6c0095 and the comment `Author` tag 1.11:1 on #1e1b4b, both on #14181d.
     Prose links get a neutral ink and an underline as their only remaining
     affordance, so the underline has to be legible on every pub: an accent-
     coloured one is invisible on exactly the dark accents that forced the ink
     to go neutral (#1e1b4b measures 1.2:1 against this canvas), and the accent
     is unreachable as a decoration colour for those pubs at any thickness.
     `.button` (accent-FILLED CTA) and `.image-link` (image wrapper) are
     text-less and stay out.
     `[class*="color-accent-"]` is the Pencraft accent-ink utility. It lands on
     whatever element owns the text, not always an anchor: the hub's leaderboard
     rank line ("#24 Rising in Technology" on every /@handle) carries it on a
     SPAN wrapping the link, so an anchor-only selector never reaches it. The
     month header is the one carrier that must keep the muted grey set above,
     and it wears both classes, so it is excluded here rather than relying on
     source order. --- */
  .body.markup a:not(.button):not(.image-link),
  a.linkified {
    color: #e6edf3 !important;
    text-decoration-line: underline !important;
    text-decoration-color: currentColor !important;
  }
  [class*="color-accent-"]:not([class*="monthHeader"]),
  a.thread-head-cta {
    color: #e6edf3 !important;
  }
  /* Search-autocomplete match highlight. It paints --color-link-fg over a
     20%-alpha wash of the same colour, so the MATCHED word ends up less legible
     than the plain result text around it (2.7:1 on a #9a6600 pub). The wash
     stays — that is the hit cue. Scoped to `pubAccentTheme-`, the wrapper the
     publication's search panel is portalled into: outside it, on the hub, the
     same class resolves --color-link-fg from the semantic-highlight blue set
     above, which is already the right colour and must not be flattened. */
  [class*="pubAccentTheme"] [class*="highlight-"] {
    color: #e6edf3 !important;
  }

  /* Comment `Author` / `Liked by …` tags feed the accent into the Tag component's
     own --color-theme-fg; the outline stays accent-tinted. */
  [class*="tag-"][class*="theme_accent"] {
    --color-theme-fg: #c4cdd6 !important;
  }

  /* --- Sticky publication nav spacer (inline-styled hardcoded white block
     reserving the header's layout height) --- */
  .main-menu > div {
    background-color: #14181d !important;
  }

  /* --- www marketing nav "Sign in" button (a bg-white Pencraft pill in the
     landing header; its text takes our light fg, so it reads near-invisible on
     white). Darken the pill to an elevated surface. --- */
  .homepage-nav [class*="bg-white"] {
    background-color: #262c33 !important;
  }

  /* --- www marketing mobile nav toggle. The lucide burger ships a hardcoded
     stroke="#3a261c" presentation attribute (the same brown as the footer
     headings), which on the dark bar measures ~1.4:1. Its <line> children carry
     no stroke of their own and inherit this one. --- */
  .homepage-nav .burger-icon,
  .homepage-nav .burger-icon * {
    stroke: #e6edf3 !important;
  }

  /* --- www marketing mobile slide-in menu (hardcoded white drawer; its links
     take our light fg and read near-invisible on white) --- */
  .homepage-nav-mobile-menu {
    background-color: #14181d !important;
  }
  /* Its item dividers ship a hardcoded light-grey section band (#f8f8f8) and
     colourless 1px link hairlines that fall back to currentColor (our light
     fg) — both render as bright white lines on the dark drawer. --- */
  .homepage-nav-mobile-menu .mobile-menu-section,
  .homepage-nav-mobile-menu .mobile-menu-section > a {
    border-color: #2d333b !important;
  }

  /* --- www marketing nav glyphs. The magnifier in the header search field, the
     back chevron and the dropdown-trigger chevrons ship hardcoded #3a261c /
     #1c110b strokes (the same brown as the burger above), ~1.25:1 on the dark
     bar. The trigger labels and the legacy dropdown links carry the same
     brown as ink. --- */
  .homepage-nav .homepage-nav-search-bar svg,
  .homepage-nav .homepage-nav-back-link svg,
  .homepage-nav .homepage-nav-for-writers > svg path,
  .homepage-nav .homepage-nav-were-hiring > svg path {
    stroke: #8b949e !important;
  }
  .homepage-nav .homepage-nav-for-writers > span,
  .homepage-nav .homepage-nav-were-hiring > span,
  .homepage-nav .dropdown-menu a {
    color: #e6edf3 !important;
  }

  /* --- Marketing / corporate pages (everything under `#substack-home` that is
     not the Pencraft app: /about, /going-paid and its per-vertical
     `cohort-page` siblings, /jobs, /startups, /sponsorships, /features,
     /podcasts, /resources, /sitemap, /substack-vs-*).
     These are hand-built pages OUTSIDE the token system: they hardcode a
     dark-brown ink (#3a261c / #392d1f / #40322a / #1c110b) and cream/white
     section fills, so none of the token work above reaches them. On the dark
     canvas the ink measures ~1.25:1, and the Pencraft copy that sits inside a
     kept-light section measures ~1.09:1 on white.
     The brand bands are deliberately NOT matched: the orange `hero-` block,
     the `testimonialBand-` purple/green/orange quotes, `finalCta-`, and the
     yellow `cardTint-`. The vs-comparison hero is reached by its own
     `aria-labelledby` because its class shape (`hero-<hash>`) is shared with
     the orange /about hero. --- */
  #substack-home .cohort-page,
  #substack-home .cohort-page .cohort-link,
  #substack-home .cohort-page .cohort-example a,
  #substack-home .cohort-page .case-study a,
  #substack-home .going-paid-guide-page,
  #substack-home .grow-page .event,
  #substack-home .jobs-page,
  #substack-home [class*="jobs-page-team"],
  #substack-home .resources-page,
  #substack-home .new-landing-page .publication,
  #substack-home .new-landing-page .publication-explanation-box .title,
  #substack-home .new-landing-page .publication-explanation-box .title > span,
  #substack-home .calculator,
  #substack-home .calculator .calculator-box .calculator-box-title,
  #substack-home .borderless-calculator-title,
  #substack-home [class*="customHeaderText"],
  #substack-home [class*="boldedCell"],
  #substack-home [class*="heroText1"],
  #substack-home [class*="partnerCardTitle"],
  #substack-home h3[class^="title-"],
  #substack-home .button.secondary {
    color: #e6edf3 !important;
  }
  /* The marketing marquee's "Subscribe" pills keep the site's white fill (they
     sit on colour-washed publication cards, and the same `bg-white` utility
     also wraps the publication logo chips, which must stay white for logo
     legibility). Only the pill LABEL follows --color-fg-primary, which our
     remap paints white-on-white, so restate the site's dark ink for text
     inside such a pill. The nav "Sign in" pill is unaffected: its label is a
     button, not a `color-` utility. */
  #substack-home [class*="bg-white"] [class*="color-primary"] {
    color: #1c2128 !important;
  }

  /* Guide/resource list glyphs ship a hardcoded black stroke. */
  #substack-home .resource-icon {
    stroke: #8b949e !important;
  }
  /* Hairlines across the marketing pages are hardcoded light greys
     (#cacaca/#d8d8d8/#e3e3e3/#e5e5e5/#e6e6e6/#e8e8e8): resource cards and their
     row rules, the guide's sticky section rail, the secondary-CTA outline, the
     cohort section dividers, the per-cookie boxes on /privacy, the comparison
     table rows and the FAQ dividers.
     `tr` is safe unqualified here — `#substack-home` is absent from every
     Pencraft app page. */
  #substack-home .featured-resource,
  #substack-home .resource,
  #substack-home .floating-navigator,
  #substack-home .button.big-button.secondary,
  #substack-home .cohort-hero,
  #substack-home .cohort-big-benefits,
  #substack-home .cohort-examples,
  #substack-home .cohort-substack-benefits,
  #substack-home .blogger-hero,
  #substack-home .case-study-section,
  #substack-home section.cookie,
  #substack-home [class*="containerBorderBottom"],
  #substack-home [class*="containerBorderTop"],
  #substack-home [class*="faqItem"],
  #substack-home tr,
  #substack-home hr {
    border-color: #2d333b !important;
  }
  #substack-home .featured-byline {
    color: #8b949e !important;
  }

  /* Muted body copy on the brand-partnership routes (/sponsorships and its
     /sponsorships-signup flow), which hardcode #777 / #6b6b6b — greys picked
     against a cream band, so they measure 3.3-4.0:1 once the band goes dark.
     Everything is anchored to the route's own `page-` wrapper: the module
     stems are NOT unique to these routes (`heroSubtitle-` is white-on-orange
     in the /about hero, `statLabel-` is already-light copy on /about), and an
     unanchored stem repaints those grey. The loose `[class*="page-"]` is safe
     as an ANCESTOR — it also matches the `homepage-nav*` family, but none of
     these stems live in the nav.
     Each stem carries its trailing `-` so the hash-suffixed base class is hit
     without swallowing a longer sibling: `categoryTab-` must not reach
     `categoryTabActive-`, whose #eee-on-#161718 selected state is correct.
     `statLabel` appears in both capitalisations across the two modules. --- */
  #substack-home [class*="page-"] [class*="heroSubtitle-"],
  #substack-home [class*="page-"] [class*="heroDescription-"],
  #substack-home [class*="page-"] [class*="sectionDescription-"],
  #substack-home [class*="page-"] [class*="bulletText-"],
  #substack-home [class*="page-"] [class*="statLabel-"],
  #substack-home [class*="page-"] [class*="StatLabel-"],
  #substack-home [class*="page-"] [class*="testimonialCardPub-"],
  #substack-home [class*="page-"] [class*="testimonialCardQuote-"],
  #substack-home [class*="page-"] [class*="bottomCtaDescription-"],
  #substack-home [class*="page-"] [class*="categoryTab-"],
  #substack-home [class*="page-"] [class*="campaignPromptDescription-"],
  #substack-home [class*="page-"] [class*="stepIndicator-"],
  #substack-home [class*="page-"] [class*="legalText-"],
  #substack-home [class*="page-"] [class*="legalLink-"],
  #substack-home [class*="page-"] [class*="waysToPartnerSubtitle-"],
  #substack-home [class*="page-"] [class*="waysToPartnerCaption-"],
  #substack-home [class*="page-"] [class*="partnerCardDescription-"],
  #substack-home [class*="page-"] [class*="valuePropCopy-"] p,
  #substack-home [class*="page-"] [class*="becomeSponsorSubtitle-"],
  #substack-home [class*="page-"] [class*="becomeSponsorSectionLabel-"],
  #substack-home [class*="page-"] [class*="becomeSponsorLegal-"],
  #substack-home .calculator-fineprint,
  #substack-home .borderless-calculator-fineprint,
  #substack-home .cohort-page .form-info {
    color: #8b949e !important;
  }

  /* /sponsorships-signup splits the viewport into a photo panel and a form
     panel; the form panel and the page behind it keep a hardcoded #f8f6f1,
     so every label takes our light fg and lands at ~1.1:1. The photo panel is
     already #1a1a1a and stays.
     The `page-` stems are matched at a word boundary — a bare `[class*="page-"]`
     would also swallow the whole `homepage-nav*` family. --- */
  #substack-home [class^="page-"],
  #substack-home [class*=" page-"],
  #substack-home [class*="page-"] [class*="rightPanel-"] {
    background-color: #14181d !important;
  }
  /* Its "Back" button is drawn for that cream: #1a1a1a ink inside a 15%-black
     hairline, and a 4%-black hover wash. All three vanish once the panel is
     dark, leaving an invisible control beside the orange submit. */
  #substack-home [class*="page-"] [class*="secondaryButton-"] {
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  #substack-home [class*="page-"] [class*="secondaryButton-"]:hover {
    background-color: #262c33 !important;
  }

  /* The /features closing CTA paints its body copy with the light-scheme
     SURFACE primitive (`color: var(--color-light-bg-primary)`) so that it
     reads white on the green band. We remap that primitive to #14181d, which
     lands dark-on-green at ~1.9:1 — restate the white it stands for. */
  #substack-home [class*="finalCtaBody"] {
    color: #ffffff !important;
  }

  /* The event pill draws its outline in the same brown as its ink. */
  #substack-home .cohort-page .event-item .hosted-pill {
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Full-bleed light section fills. The tinted/who/gradient members also paint
     a peach wash as background-IMAGE over the fill, which a background-color
     override alone does not clear.
     The three `^=` members are /jobs bands whose whole fill is a cream RASTER
     (no CSS gradient to read, so the bg-image scan is blind to them). They must
     be prefix-matched: `[class*="jobsHero"]` would also swallow the orange
     jobsHeroButton and the jobsHeroImage that sit inside the band. */
  #substack-home [class*="statsStrip"],
  #substack-home [class^="jobsHero-"],
  #substack-home [class^="buildSection-"],
  #substack-home [class^="marqueeBackground-"],
  #substack-home [class*="sectionTinted"],
  #substack-home [class*="sectionWhite"],
  #substack-home [class*="sectionWho"],
  #substack-home [class*="sectionCream"],
  #substack-home [class*="toolsSection"],
  #substack-home [class*="topGradientRegion"],
  #substack-home [class*="bottomGradientRegion"],
  #substack-home [class*="testimonialImagePane"],
  #substack-home [class*="heroLogoBackdrop"],
  #substack-home section[class*="valueProp"],
  #substack-home section[class*="waysToPartner"],
  #substack-home section[class*="becomeSponsor"],
  #substack-home section[class*="testimonial-"],
  #substack-home [class*="jobPerks"],
  #substack-home section[aria-labelledby="hero-heading"] {
    background-color: #14181d !important;
    background-image: none !important;
  }
  /* The sponsorship partner wordmarks are black-linework PNGs drawn for the
     cream bands darkened just above, so they land black-on-dark. Invert their
     lightness; the hue-rotate keeps any colour inside the mark. Scoped to the
     logo strip and the quote band — the surrounding hero holds photographs
     that must not be touched. */
  #substack-home [class*="logoStripImage"],
  #substack-home section[class*="testimonial-"] img {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Cards and panels that sit ON those sections take the elevated surface. */
  #substack-home [class*="benefitCard"],
  #substack-home [class*="heroCard"],
  #substack-home [class*="heroCreatorCard"],
  #substack-home [class*="compareTableScrollInn"],
  #substack-home [class*="startOptionCard"],
  #substack-home [class*="press-grid"] > div,
  #substack-home .borderless-calculator,
  #substack-home .calculator .calculator-box,
  #substack-home .going-paid-guide-page .banner,
  #substack-home .resources-page .banner {
    background-color: #1c2128 !important;
    background-image: none !important;
  }

  /* --- www marketing footer (global site footer ships a hardcoded light-grey
     block with dark-brown column headings) --- */
  .www-footer {
    background-color: #14181d !important;
  }
  .www-footer h1,
  .www-footer h2,
  .www-footer h3,
  .www-footer h4 {
    color: #e6edf3 !important;
  }

  /* --- Discover / not-found marketing landing hero (hardcoded dark-brown
     display heading, not token-driven) --- */
  .new-landing-page .display-type {
    color: #e6edf3 !important;
  }

  /* --- Text selection --- */
  ::selection {
    background-color: rgba(95, 176, 230, 0.3);
  }
}

@-moz-document domain("support.substack.com") {
/* --gray-lightest and --gray-lighter are consumed only as background and
     border colours (breadcrumb bar, article box, vote footer, blockquotes,
     search filter rail), so both move to surfaces. --gray-light is left alone:
     it is used for BOTH roles and its #818a91 still measures 4.6:1 as ink. */
  :root {
    --gray-lighter: #262c33 !important;
    --gray-lightest: #1c2128 !important;
    --meta-text-color: #8b949e !important;
    --input-border-color: #2d333b !important;
    --input-focus-border-color: #4a515a !important;
  }

  /* `body { color: #282f48 }` is what every heading, paragraph and article
     inherits; the rest of the list is each place the theme restates that ink
     (or the footer's #101010) on a component of its own. */
  body,
  .lt-skip-navigation,
  .lt-topbar__link,
  .lt-topbar__controls,
  .lt-btn--topbar,
  .lt-btn--print,
  .breadcrumbs > li:last-child a,
  .lt-contact-box,
  .lt-contact-box__title,
  .lt-custom-block__title,
  .lt-custom-block__link,
  .lt-section-link,
  .lt-article-box,
  .lt-search-filter__link,
  .lt-profile-stats__value,
  .lt-profile-nav__item a,
  .lt-promoted-articles-accordion-item__title,
  .lt-my-activities-menu--main .lt-my-activities-menu-item.is-active,
  .lt-vote__control--active,
  .lt-post-status--not-planned,
  .lt-status-label--not-planned,
  .recent-articles ul > li a,
  .related-articles ul > li a,
  .tabs-link,
  .upload-dropzone span,
  .lt-footer,
  .lt-footer__social-link,
  .callout {
    color: #e6edf3 !important;
  }

  /* The theme's link green (#006f5c) measures 2.8:1 on this canvas. #0c9 is
     the site's own brighter green, the one its "solved" label uses. The bare
     `a` carries no !important on purpose: the white-on-brand links
     (hero, orange block-list tiles, primary buttons) then keep winning on
     specificity, exactly as they do natively. */
  a {
    color: #00cc99;
  }
  /* The floating "return to top" control is the one place the theme spends the
     green as INK rather than as a fill: glyph and outline both #006f5c (2.9:1
     here), and its hover goes DARKER still (#003229, 1.4:1) because on white
     that reads as pressed. It is a `button`, so the `a` rule above misses it,
     and it only enters the viewport once the theme's own JS adds `.is-active`
     (it parks at `bottom: -50px`). Hover moves up the ramp, not down. */
  .lt-scroll-to-top {
    color: #00cc99 !important;
    border-color: #00cc99 !important;
  }
  .lt-scroll-to-top:hover,
  .lt-scroll-to-top:focus {
    color: #66e0bd !important;
    border-color: #66e0bd !important;
  }

  /* Breadcrumb ancestors are a hardcoded #6b7280 (3.7:1 on this canvas) rather
     than the --meta-text-color the rest of the metadata uses. The current crumb
     keeps the bright ink from the list above — its `:last-child` selector
     outranks this one. The `›` separators are a pseudo carrying the same grey. */
  .breadcrumbs > li a,
  .breadcrumbs > li + li::before {
    color: #8b949e !important;
  }

  .lt-footer__copyright a,
  .lt-topbar__link:hover,
  .lt-topbar__link:focus,
  .lt-topbar__link:active,
  .lt-btn--topbar:hover,
  .lt-btn--topbar:focus,
  .lt-btn--topbar:active {
    color: #00cc99 !important;
  }

  /* Light surfaces the theme hardcodes; the --gray-* remap above already
     carries the breadcrumb bar, article box, vote footer and blockquotes. */
  .lt-topbar,
  .lt-footer {
    background-color: #14181d !important;
  }
  .lt-skip-navigation,
  .lt-topbar__controls,
  .lt-dropdown-menu,
  .table .table {
    background-color: #1c2128 !important;
  }
  .lt-dropdown-menu [role="menuitem"]:hover,
  .lt-dropdown-menu [role="menuitem"]:focus,
  .accordion--default .accordion__item-title--active {
    background-color: #262c33 !important;
    color: #e6edf3 !important;
  }

  /* Focused search field: the theme repaints it solid white on focus, which
     with the light ink above leaves the query invisible while it is typed. */
  .lt-search-box #query:focus {
    background-color: #1c2128 !important;
    border-color: #4a515a !important;
  }

  /* Callouts and notifications carry their meaning in the left/edge border
     colour, which stays; only the pale fill moves to an elevated surface. */
  .callout--success,
  .callout--info,
  .callout--warning,
  .callout--danger,
  .callout--primary,
  .notification-error,
  .notification-notice,
  .notification-alert,
  .notification-inline {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* Search hit highlight is a background-only rule, so the light ink above
     would land on its pale yellow. */
  .lt-search-result__text em {
    color: #14181d !important;
  }
}
